<script setup lang="ts">
import { programmes, type WorkshopEvent } from '~~/shared/catalogue'
defineProps<{events:WorkshopEvent[];unavailable:boolean}>()
defineEmits<{select:[programme:string,eventId?:string]}>()
const {t,locale}=useCopy()
const showOthers=ref(false)
const visibleProgrammes=computed(()=>[...programmes].sort((a,b)=>Number(b.id==='fundamental')-Number(a.id==='fundamental')).filter(p=>showOthers.value||p.id==='fundamental'))
function date(value:string){ return new Intl.DateTimeFormat(locale.value==='vi'?'vi-VN':'en-GB',{dateStyle:'medium',timeZone:'Asia/Ho_Chi_Minh'}).format(new Date(value)) }
</script>
<template><section id="workshops" class="section"><div class="wrap"><div class="section-head"><h2 v-html="t('workshops.title')" /><p>{{ t('workshops.intro') }}</p></div><p v-if="unavailable" class="muted" role="status">{{ t('workshops.unavailable') }}</p><div class="cards workshop-cards" :class="{single:!showOthers}"><article v-for="p in visibleProgrammes" :key="p.id" class="card" :class="{featured:p.id==='fundamental'}"><span class="eyebrow">{{ t(`${p.id}.tag`) }}</span><h3>{{ p.name }}</h3><p>{{ t(`${p.id}.title`) }}</p><p>{{ t(`${p.id}.body`) }}</p><template v-if="events.some(e=>e.programmeId===p.id)"><div v-for="event in events.filter(e=>e.programmeId===p.id)" :key="event.id" class="event"><p>{{ date(event.startsAt) }} – {{ date(event.endsAt) }}<br>{{ event.location }}</p><p>{{ t('workshops.fee') }}: {{ event.feeVnd===null?t('workshops.tbc'):new Intl.NumberFormat(locale==='vi'?'vi-VN':'en-US',{style:'currency',currency:'VND'}).format(event.feeVnd) }}</p><button class="btn" @click="$emit('select',p.id,event.id)">{{ t(event.status==='full'?'workshops.full':'workshops.open') }}</button></div></template><template v-else><p class="small" v-html="t(`${p.id}.facts`)" /><button class="btn" @click="$emit('select',p.id)">{{ t(`${p.id}.cta`) }}</button></template></article></div><p class="small">{{ t('workshops.note') }}</p><button v-if="!showOthers" class="textlink other-workshops" @click="showOthers=true">{{ t('workshops.other') }} +</button></div></section></template>
